import{n as e}from"./rolldown-runtime-C0FnF6B9.js";var t,n,r,i,a;function o(){return(o=e((()=>{t=`0.10.0`,n=`2026-10-17`,r=[{title:{en:`Synara 1.0.6 in the Agent panel`,zh:`Agent 面板升级到 Synara 1.0.6`},body:{en:`The bundled agent runtime moves to Synara 1.0.6.`,zh:`内置的智能体运行时升级到 Synara 1.0.6。`}},{title:{en:`Smoother long documents`,zh:`长文档更流畅`},body:{en:`Typing no longer re-renders the PDF preview on every keystroke.`,zh:`输入时不再每次按键都重新渲染 PDF 预览。`}},{title:{en:`A clearer TODOs panel`,zh:`更清晰的 TODO 面板`},body:{en:`TODOs are grouped by file, with a new illustration when there is nothing left to do.`,zh:`TODO 按文件分组，全部完成时会显示一幅新插图。`}},{title:{en:`A tidier submission checklist`,zh:`更整洁的投稿检查清单`},body:{en:`The figure inventory and limits have more room.`,zh:`图片清单和篇幅限制有了更宽裕的空间。`}},{title:{en:`A more focused Lattice`,zh:`更专注的 Lattice`},body:{en:`The Review, Find support, Terms and Responses tools have been removed. Data they saved in your projects stays on disk untouched.`,zh:`审阅、查找支撑文献、术语和审稿回复工具已移除。它们保存在项目中的数据仍原样保留在磁盘上。`}}],i=[],a={version:t,date:n,highlights:r,fixes:i}})))()}var s,c,l,u,d;function f(){return(f=e((()=>{s=`0.10.1`,c=`2026-10-18`,l=[{title:{en:`Faster Mermaid diagrams in Markdown`,zh:`Markdown 中的 Mermaid 图表更快`},body:{en:`Mermaid diagrams now render with Pele instead of mermaid.js, so the app is lighter and diagrams draw faster. They follow Lattice's light and dark theme, and a diagram that can't be drawn shows a clear error. Layouts may differ slightly from before.`,zh:`Mermaid 图表现在使用 Pele 而非 mermaid.js 渲染，应用更轻巧，图表绘制更快。图表会跟随 Lattice 的浅色和深色主题，无法绘制时会显示清晰的错误提示。布局可能与之前略有不同。`}}],u=[],d={version:s,date:c,highlights:l,fixes:u}})))()}var p,m,h,g,_;function v(){return(v=e((()=>{p=`0.11.0`,m=`2026-10-19`,h=[{icon:`shapes`,title:{en:`A built-in terminal`,zh:`内置终端`},body:{en:"Open a Terminal panel across the foot of the workspace with ⌃` (or from the Panels menu): each tab is your login shell, started in the project folder, and it follows Lattice's light and dark theme and your code theme.",zh:"按 ⌃`（或从“面板”菜单）在工作区底部打开终端面板：每个标签页都是你的登录 shell，从项目文件夹启动，并跟随 Lattice 的浅色和深色主题以及你的代码主题。"}},{icon:`gauge`,title:{en:`Faster, calmer loading`,zh:`加载更快、更安静`},body:{en:`Each load shows one placeholder shaped like what it is loading instead of a spinner stacked on a skeleton, and a rebuilt PDF appears sooner. pdfLaTeX builds reuse a cached preamble, and a refresh redraws only the pages that changed.`,zh:`每次加载只显示一个与待加载内容形状一致的占位，不再在骨架屏上叠加加载动画，重新构建的 PDF 也会更快出现。pdfLaTeX 构建会复用缓存的导言区，刷新时只重绘发生变化的页面。`}},{icon:`menu`,title:{en:`Preview tabs and pinning`,zh:`预览标签页和固定标签页`},body:{en:`A quick look from the Project tree, Quick open or project search opens in an italic preview tab that the next quick look replaces; edit it or double-click its tab to keep it. Pin tabs to keep them, and when a panel runs out of room Lattice closes its least recently used tab.`,zh:`从项目树、快速打开或项目搜索中快速查看的文件会在斜体的预览标签页中打开，下一次快速查看会替换它；编辑它或双击其标签即可保留。固定的标签页会一直保留，当面板放不下更多标签页时，Lattice 会关闭最久未使用的那个。`}},{icon:`feather`,title:{en:`Live preview for LuaLaTeX`,zh:`LuaLaTeX 实时预览`},body:{en:`The paragraph you are typing appears in the PDF as you type, while the full build waits for a pause and runs quietly. It is on by default in LuaLaTeX projects, new blank projects now use LuaLaTeX, and it can be turned off per project.`,zh:`你正在输入的段落会随着输入出现在 PDF 中，而完整构建会等你停顿后再安静地运行。LuaLaTeX 项目默认开启实时预览，新建的空白项目现在使用 LuaLaTeX，也可以按项目关闭。`}},{icon:`bot`,title:{en:`Synara 1.0.7 in the Agent panel`,zh:`Agent 面板升级到 Synara 1.0.7`},body:{en:`The bundled agent runtime moves to Synara 1.0.7, and startup no longer opens Cursor's sign-in page.`,zh:`内置的智能体运行时升级到 Synara 1.0.7，启动时也不再打开 Cursor 的登录页面。`}}],g=[{en:`A save no longer conflicts with your own earlier save when you type, undo and retype quickly.`,zh:`快速输入、撤销再重新输入时，保存不会再与你自己之前的保存冲突。`},{en:`The selection toolbar stays hidden while an input method is composing.`,zh:`输入法正在组字时，选区工具栏会保持隐藏。`},{en:`Panel tabs have a little more room from the panel's edges.`,zh:`面板标签页与面板边缘之间留出了更多空间。`}],_={version:p,date:m,highlights:h,fixes:g}})))()}var y,b,x,S,C;function w(){return(w=e((()=>{y=`0.11.1`,b=`2026-10-20`,x=[{title:{en:`No more flashes when opening files`,zh:`打开文件不再闪烁`},body:{en:`A file now opens straight into the view it will stay in. Markdown and HTML previews show a page-shaped placeholder instead of their source, text no longer rewraps once the fonts arrive, and a LaTeX file with comments shows its comment margin from the first frame.`,zh:`文件现在会直接以最终视图打开。Markdown 和 HTML 预览显示页面形状的占位，而不是先显示源码；字体加载后文字不再重新换行；带批注的 LaTeX 文件从第一帧起就显示批注边栏。`}},{title:{en:`Smoother tab dragging`,zh:`标签拖动更流畅`},body:{en:`Dragging a tab to another panel follows the pointer smoothly, and panels lay out once when they come to rest.`,zh:`把标签拖到另一个面板时会流畅地跟随指针，面板在停稳后只重新布局一次。`}},{title:{en:`A formatting toolbar in Markdown source mode`,zh:`Markdown 源码模式中的格式工具栏`},body:{en:`Selecting text in the Markdown source editor shows the same toolbar as the visual editor: block type, bold, italic, links, inline math and more, written as Markdown.`,zh:`在 Markdown 源码编辑器中选中文字时，会显示与可视化编辑器相同的工具栏：块类型、粗体、斜体、链接、行内公式等，并以 Markdown 语法写入。`}}],S=[{en:`Footnote controls line up with the note's first line, + adds a block below the last block, and clicking beside a footnote puts the cursor in its text.`,zh:`脚注的控件与注释首行对齐，+ 可以在最后一个块下方添加块，点击脚注旁边会把光标放进脚注文字中。`},{en:`Menus opened from the selection toolbar appear above the toolbar instead of under it.`,zh:`从选区工具栏打开的菜单显示在工具栏上方，不再被工具栏遮住。`},{en:`The Terminal panel no longer opens with a hint line, and moving it no longer prints the prompt twice.`,zh:`终端面板打开时不再显示提示行，移动面板也不再重复打印提示符。`},{en:`Jumping from the source to the PDF works for projects inside a symlinked folder.`,zh:`位于符号链接文件夹中的项目也能从源码跳转到 PDF。`}],C={version:y,date:b,highlights:x,fixes:S}})))()}var T,E,D,O,k;function A(){return(A=e((()=>{T=`0.11.2`,E=`2026-10-20`,D=[],O=[{en:`The file tree keeps up with the disk: files added, renamed or deleted outside Lattice appear without reopening the project, and Refresh file tree (in the tree's context menu, the Project panel's ⋯ menu and the command palette) rescans on demand without scrolling the list back to the open file.`,zh:`文件树与磁盘保持同步：在 Lattice 之外新增、重命名或删除的文件无需重新打开项目即可显示；「刷新文件树」（位于文件树右键菜单、项目面板的 ⋯ 菜单和命令面板）可随时重新扫描，且不会把列表滚回当前打开的文件。`},{en:`A main document inside a subfolder now builds beside itself, so the PDF preview shows its fresh output and jumping between source and PDF works.`,zh:`子文件夹中的主文档现在会在其所在位置编译，PDF 预览会显示最新输出，源码与 PDF 之间的跳转也能正常工作。`}],k={version:T,date:E,highlights:D,fixes:O}})))()}var j,M,N,P,F;function I(){return(I=e((()=>{j=`0.11.3`,M=`2026-10-20`,N=[],P=[{en:`Live preview now matches the real build: citations and the bibliography no longer turn into [?] in the preview, and a root document inside a subfolder shows the real build output instead of differently laid-out pages.`,zh:`实时预览现在与真实构建一致：预览中的引用和参考文献不再显示为 [?]，位于子文件夹中的主文档也会显示真实的构建结果，而不是排版不同的页面。`}],F={version:j,date:M,highlights:N,fixes:P}})))()}var L,R,z,B,V;function H(){return(H=e((()=>{L=`0.11.4`,R=`2026-10-21`,z=[],B=[{en:`The PDF now rebuilds automatically after the Agent, a terminal agent, or any other program edits your project files: about 1.5 s after the edits settle, with one build per burst of changes. Manual auto-build still never builds on its own.`,zh:`现在，当 Agent、终端中的 Agent 或任何其他程序修改项目文件后，PDF 会自动重新编译：在修改停止约 1.5 秒后开始，同一批连续修改只编译一次。“手动”自动编译模式仍然不会自行编译。`}],V={version:L,date:R,highlights:z,fixes:B}})))()}var U,W,G,K,q;function J(){return(J=e((()=>{U=`0.11.5`,W=`2026-10-21`,G=[],K=[{en:`Live preview now works for a main document in a subfolder, such as cv/sop/sop.tex, and lays it out the same as the real build: its bibliography, \\input files and figures resolve from the document's own folder.`,zh:`实时预览现在支持位于子文件夹中的主文档（例如 cv/sop/sop.tex），排版与正式编译一致：参考文献、\\input 文件和图片都从文档所在的文件夹解析。`},{en:`The selected file in the file tree no longer flickers while you scroll.`,zh:`文件树中选中的文件在滚动时不再闪烁。`}],q={version:U,date:W,highlights:G,fixes:K}})))()}var Y,X,Z,Q,$;function ee(){return(ee=e((()=>{Y=`0.11.6`,X=`2026-10-22`,Z=[],Q=[{en:`Selecting text in the PDF works again: the highlight shows on live-preview pages and in the dark theme.`,zh:`PDF 中的文字选择恢复正常：实时预览页面和深色主题下都会显示选区高亮。`},{en:`Typing \\includegraphics no longer turns into \\include{graphics}.`,zh:`输入 \\includegraphics 时不再被变成 \\include{graphics}。`},{en:`Renaming a .tex file no longer deletes PDFs with the same name.`,zh:`重命名 .tex 文件时不再删除同名的 PDF。`},{en:`Compile errors are no longer lost or pointed at the wrong file.`,zh:`编译错误不再丢失，也不再指向错误的文件。`},{en:`Overleaf track changes are respected when you edit, and tracked deletions are shown in the right place.`,zh:`编辑时会遵循 Overleaf 的修订跟踪，被跟踪的删除内容也会显示在正确的位置。`},{en:`Folder rows that stick to the top of the file tree no longer overlap the rows scrolling under them.`,zh:`文件树中吸顶的文件夹行不再与下方滚动的行重叠。`},{en:`Resolving or deleting a comment now confirms what happened and offers Undo.`,zh:`解决或删除评论后会提示操作结果，并提供撤销。`},{en:`Comment details: a delete button, a centred reply field, a seamless popover arrow and a better-sized gutter pin.`,zh:`评论细节改进：新增删除按钮，回复框居中，弹出框箭头无缝衔接，侧边栏标记尺寸更合适。`},{en:`The caret in the agent panel is drawn at text height.`,zh:`智能体面板中的光标高度与文字一致。`}],$={version:Y,date:X,highlights:Z,fixes:Q}})))()}var te,ne,re,ie,ae;function oe(){return(oe=e((()=>{te=`0.11.7`,ne=`2026-10-23`,re=[],ie=[{en:`A calmer interface: taglines, helper text and secondary labels are gone across the app.`,zh:`界面更清爽：全应用移除了标语、辅助说明和次要标签。`},{en:`Overleaf: documents created in the browser now sync as tracked suggestions when track changes is on.`,zh:`Overleaf：开启修订跟踪时，在浏览器中新建的文档现在会以修订建议的形式同步。`},{en:`Pinned folders at the top of the file tree stay clean while you scroll fast.`,zh:`快速滚动时，文件树顶部固定的文件夹保持整洁。`}],ae={version:te,date:ne,highlights:re,fixes:ie}})))()}var se,ce,le,ue,de;function fe(){return(fe=e((()=>{se=`0.11.8`,ce=`2026-10-23`,le=[],ue=[{en:`Builds now carry on past LaTeX errors and show every error, keeping a PDF on screen: the errored PDF, or the last good one. Turn on Stop on first error per project to get the old behaviour.`,zh:`编译现在会越过 LaTeX 错误继续进行，并显示全部错误，同时保留 PDF 在屏幕上：出错时的 PDF 或上一次成功的 PDF。如需恢复旧行为，可按项目开启“遇到首个错误即停止”。`},{en:`Agent panel updated to Synara 1.0.8: a running-agents capsule above the composer, complete diffs while a turn runs, Codex warnings shown, provider hand-off, and a new-chat button in the tab bar.`,zh:`Agent 面板更新至 Synara 1.0.8：输入框上方新增运行中智能体胶囊、回合进行中即可查看完整差异、显示 Codex 警告、支持切换提供方接力，标签栏新增新建对话按钮。`},{en:`Presentations updated to Open Slide 2.3.1.`,zh:`演示文稿更新至 Open Slide 2.3.1。`},{en:`Settings section headings are back, and the project dictionary row lines up with the rest.`,zh:`设置中的分区标题已恢复，项目词典一行也与其他行对齐了。`}],de={version:se,date:ce,highlights:le,fixes:ue}})))()}var pe,me,he,ge,_e;function ve(){return(ve=e((()=>{pe=`0.12.0`,me=`2026-10-25`,he=[{title:{en:`Full-text search across your papers`,zh:`论文全文检索`},body:{en:`Type in the Papers panel's search box to search the full text of the project's papers: results are ranked by relevance, each paper shows its matching lines with the words highlighted, and clicking a line opens the paper at that line. Chinese is supported, and the agent searches the same index.`,zh:`在论文库面板的搜索框中输入，即可检索项目中论文的全文：结果按相关度排序，每篇论文列出匹配的行并高亮关键词，点击某一行即可在该行打开论文。支持中文，AI 助手也使用同一索引进行检索。`}},{icon:`shapes`,title:{en:`Open Slide works with the Agent panel`,zh:`Open Slide 与 Agent 面板协同`},body:{en:`A presentation shows when the Lattice agent is editing the deck, and Open Slide's Apply comments, Draft a deck and Ask AI now open in the Agent panel.`,zh:`Lattice 智能体编辑演示文稿时，演示文稿会显示提示；Open Slide 的“应用批注”“起草演示文稿”和“询问 AI”现在会在 Agent 面板中打开。`}},{icon:`bot`,title:{en:`See what the agent is doing`,zh:`查看智能体正在做什么`},body:{en:`The Agent panel shows what the current turn is working on.`,zh:`Agent 面板会显示当前回合正在进行的工作。`}}],ge=[],_e={version:pe,date:me,highlights:he,fixes:ge}})))()}var ye,be,xe,Se,Ce;function we(){return(we=e((()=>{ye=`0.12.1`,be=`2026-10-30`,xe=[],Se=[{en:`Please install this version manually, once. It is signed with a new update key, so Lattice 0.12.0 and earlier will not update to it automatically: download the DMG below and drag it into Applications over your current copy. Your projects and settings are kept, and later updates are automatic again.`,zh:`请手动安装此版本一次。此版本使用新的更新密钥签名，Lattice 0.12.0 及更早版本不会自动更新到它：请下载下方的 DMG，并将其拖入“应用程序”文件夹覆盖当前版本。你的项目和设置都会保留，之后的更新将恢复自动进行。`},{en:`Lattice opens again on macOS 14, where the PDF preview crashed it on launch.`,zh:`Lattice 在 macOS 14 上可以正常打开了，此前 PDF 预览会导致其启动时崩溃。`},{en:`Overleaf: your edits no longer stop reaching your local files after the computer sleeps or the network changes.`,zh:`Overleaf：电脑睡眠或网络切换后，你的编辑不会再无法同步到本地文件。`},{en:`Agent panel updated to Synara 1.0.9: /goal posts a visible message, Stop keeps your queued messages with Continue and Edit, and a turn cut off by a restart shows a readable error with Continue task.`,zh:`Agent 面板更新至 Synara 1.0.9：/goal 会发送一条可见的消息；点击停止后会保留排队中的消息，并可选择继续或编辑；因重启而中断的回合会显示易读的错误信息，并提供“继续任务”。`},{en:`Complete third-party license notices.`,zh:`第三方许可声明已补全。`}],Ce={version:ye,date:be,highlights:xe,fixes:Se}})))()}var Te,Ee,De,Oe,ke;function Ae(){return(Ae=e((()=>{Te=`0.13.0`,Ee=`2026-11-01`,De=[{icon:`bot`,title:{en:`The agent looks at a figure before inserting it`,zh:`Agent 插入图表前会先看一眼`},body:{en:`When the agent draws a TikZ or PGFPlots figure, it now typesets it with your paper's preamble at column width and checks the picture, so labels over curves, legends over data and plots wider than the column are fixed before the figure reaches your paper. Your build, PDF and SyncTeX are left alone, and the insertion can be reviewed and undone like any agent edit.`,zh:`Agent 绘制 TikZ 或 PGFPlots 图表时，会先用论文自己的导言区按栏宽排版并检查图像，在图表进入论文之前修正标签压住曲线、图例遮挡数据或图宽超出栏宽等问题。你的编译、PDF 和 SyncTeX 都不受影响，插入操作也能像其他 Agent 编辑一样审阅和撤销。`}},{icon:`feather`,title:{en:`Smoother LaTeX input`,zh:`更顺手的 LaTeX 输入`},body:{en:`Enter on an \\item line starts the next item, and on an empty item leaves the list. Typing \\left( or \\bigl[ writes the matching \\right) or \\bigr]. Hovering a \\ref or \\eqref shows the equation with its number and page. %novalidate lines and regions get no LaTeX diagnostics, and ⌥⌘M opens a searchable math symbol palette.`,zh:`在 \\item 行按回车会开始下一项，在空项上按回车则退出列表。输入 \\left( 或 \\bigl[ 会自动写好对应的 \\right) 或 \\bigr]。悬停在 \\ref 或 \\eqref 上会显示公式及其编号和页码。%novalidate 行和区域不再显示 LaTeX 诊断，⌥⌘M 可打开可搜索的数学符号面板。`}},{title:{en:`Submission checks for double-blind venues`,zh:`面向双盲会议的投稿检查`},body:{en:`The submission checklist flags what reviewers would catch: a template option that prints the authors, acknowledgements or \\thanks left in, links to your own code accounts, author names in the PDF's metadata, and Type 3 or unembedded fonts.`,zh:`投稿检查清单会标出审稿人可能发现的问题：会打印作者信息的模板选项、遗留的致谢或 \\thanks、指向你自己代码账号的链接、PDF 元数据中的作者姓名，以及 Type 3 字体或未嵌入的字体。`}},{title:{en:`Grammar checks tuned for papers`,zh:`为论文调校的语法检查`},body:{en:`LaTeX is checked with an academic profile that accepts common paper usage and abbreviations. Choose American or British English and switch single rules in Settings, and ignore a sentence or a rule for the whole project from a suggestion.`,zh:`LaTeX 文档使用学术配置进行检查，接受论文中常见的用法和缩写。可在设置中选择美式或英式英语并单独开关各条规则，也可以从建议中忽略某个句子，或在整个项目中忽略某条规则。`}}],Oe=[{en:`A double-click in the PDF lands on the word you clicked, not just its line.`,zh:`在 PDF 中双击会定位到你点击的那个词，而不只是那一行。`},{en:`Your last edits are saved before a window closes, Lattice quits, or the page reloads, and an error in one panel stays in that panel instead of taking down the window.`,zh:`窗口关闭、Lattice 退出或页面重新加载前，会保存你最后的编辑；某个面板出错时只影响该面板，不会导致整个窗口崩溃。`},{en:`The outline reads headings the way TeX does, skipping comments, verbatim and macro bodies.`,zh:`大纲会按 TeX 的方式读取标题，跳过注释、verbatim 和宏定义内容。`},{en:`Label and citation checks keep working when a project has unreadable files, and citations update when a .bib changes outside the editor.`,zh:`项目中存在无法读取的文件时，标签和引用检查仍能正常工作；在编辑器外修改 .bib 后，引用也会随之更新。`},{en:`A compile error opens the exact file it names, and a path whose letter case differs from the file on disk is reported as such, including before arXiv export.`,zh:`编译错误会打开它所指的那个文件；路径大小写与磁盘上的文件不一致时会如实提示，arXiv 导出前也会检查这一点。`},{en:`Files with Windows (CRLF) line breaks keep them when saved.`,zh:`使用 Windows (CRLF) 换行符的文件在保存后会保留原有换行符。`},{en:`Edit › Select All selects the whole document.`,zh:`编辑 › 全选会选中整个文档。`},{en:`Typing " or ' in LaTeX inserts one character instead of an auto-closed pair.`,zh:`在 LaTeX 中输入 " 或 ' 只会插入一个字符，不再自动补全成一对。`},{en:`Words with TeX accents, such as na\\"ive, are no longer flagged as misspellings.`,zh:`带 TeX 重音的单词（如 na\\"ive）不再被标为拼写错误。`},{en:`Overleaf: files whose paths differ only in letter case are set aside instead of one being silently dropped.`,zh:`Overleaf：仅大小写不同的路径会被单独放在一边，而不是悄悄丢掉其中一个。`},{en:`The PDF redraws sharply after the window moves to a display with a different pixel density.`,zh:`窗口移到像素密度不同的显示器后，PDF 会重新清晰绘制。`},{en:`Background git reads no longer run programs named in a project's .git/config.`,zh:`后台 git 读取不再运行项目 .git/config 中指定的程序。`}],ke={version:Te,date:Ee,highlights:De,fixes:Oe}})))()}var je,Me,Ne,Pe,Fe;function Ie(){return(Ie=e((()=>{je=`0.14.0`,Me=`2026-11-01`,Ne=[{title:{en:`Chinese papers typeset and checked`,zh:`中文论文排版与检查`},body:{en:`A new Chinese article template starts a ctex paper ready to compile, and when Chinese, Japanese or Korean text is missing from the PDF, the build says so and names the fix instead of leaving blank space. New templates also cover ACL/ARR, CVPR 2027, AAAI-27, ThuThesis and ustcthesis.`,zh:`新的中文文章模板开箱即可编译 ctex 论文；当 PDF 中缺少中文、日文或韩文文字时，编译会明确指出并给出修复方法，而不是留下空白。新增模板还涵盖 ACL/ARR、CVPR 2027、AAAI-27、ThuThesis 和 ustcthesis。`}},{icon:`feather`,title:{en:`Rewrite a selection your own way`,zh:`按你的指令改写选中文字`},body:{en:`Besides the built-in rewrites, you can now type any instruction for the selected text, such as "translate into academic English" or "shorten to about 100 words", and review the result before it replaces your text.`,zh:`除了内置的改写方式，现在还可以为选中的文字输入任意指令，例如“翻译成学术英文”或“缩写到 100 词左右”，并在替换原文之前审阅结果。`}},{icon:`bot`,title:{en:`The agent uses your proxy`,zh:`Agent 使用你的代理`},body:{en:`The agent now starts with the proxy and model-provider settings from your login shell, so it works on networks that need a proxy without extra setup. When the system proxy changes, Lattice offers to restart the agent with the new one.`,zh:`Agent 现在会沿用登录 shell 中的代理和模型服务商设置，在需要代理的网络下无需额外配置即可使用。系统代理变化时，Lattice 会提示用新的代理重启 Agent。`}},{title:{en:`Grammar rules and errors in Chinese`,zh:`中文的语法规则与错误提示`},body:{en:`With the interface in Chinese, every grammar rule is named and explained in Chinese, and errors from the app itself are shown in Chinese too.`,zh:`界面为中文时，每条语法规则都有中文名称和说明，应用本身的错误信息也以中文显示。`}}],Pe=[{en:`Every way out of Lattice saves your work first, and an update never restarts the app on its own.`,zh:`退出 Lattice 的每种方式都会先保存你的工作，更新也不会再自行重启应用。`},{en:`Lattice's shortcuts work in the Agent panel and Git drawer, and ⌘W closes a tab.`,zh:`Lattice 的快捷键在 Agent 面板和 Git 抽屉中同样有效，⌘W 可关闭标签页。`},{en:`Pressing Enter or Escape to finish an input-method composition no longer submits, picks or cancels.`,zh:`用回车或 Esc 结束输入法组字时，不再误触提交、选择或取消。`},{en:`Appearance, theme and build settings changed in one window apply to every open window right away.`,zh:`在一个窗口中更改的外观、主题和编译设置会立即应用到所有打开的窗口。`},{en:`Each window is named for its project, and a large text file is called too large rather than binary.`,zh:`每个窗口以其项目命名，过大的文本文件会提示为“文件过大”而非“二进制文件”。`},{en:`Double-clicking the title bar follows your macOS setting, and full screen keeps the window buttons in place.`,zh:`双击标题栏遵循 macOS 的系统设置，全屏时窗口按钮保持原位。`},{en:`Updated the zip and KaTeX libraries past published security advisories.`,zh:`将 zip 和 KaTeX 库更新到已修复公开安全公告的版本。`}],Fe={version:je,date:Me,highlights:Ne,fixes:Pe}})))()}var Le,Re,ze,Be,Ve;function He(){return(He=e((()=>{Le=`0.14.1`,Re=`2026-11-02`,ze=[{title:{en:`A faster agent panel`,zh:`更快的智能体面板`},body:{en:`The agent panel now starts Claude before you send your first message, keeps open threads running while they sit idle, and no longer waits for Overleaf comments to refresh before sending. A new thread answers about 2 seconds sooner, and a reply after a pause comes in about half the time. Claude is now the panel's default agent.`,zh:`智能体面板现在会在你发送第一条消息前就启动 Claude，打开的对话在空闲时也会保持运行，发送消息时也不再等待 Overleaf 评论刷新。新对话的首次回答快了约 2 秒，停顿后的回复用时约减半。Claude 现在是面板的默认智能体。`}},{title:{en:`Your own MCP servers are off in the panel by default`,zh:`面板默认不再加载你自己的 MCP 服务器`},body:{en:`The agent panel now loads only Lattice's own tools, which is part of what makes it start faster. If you use your own MCP servers with Claude, turn on Load my MCP servers in Claude in Settings to bring them back.`,zh:`智能体面板现在只加载 Lattice 自带的工具，这也是它启动更快的原因之一。如果你在 Claude 中使用自己的 MCP 服务器，请在设置中打开“Load my MCP servers in Claude”（在 Claude 中加载我的 MCP 服务器）以恢复它们。`}}],Be=[{en:`The effort level shown in the agent panel is now the one actually sent to the agent.`,zh:`智能体面板中显示的推理强度现在就是实际发送给智能体的强度。`}],Ve={version:Le,date:Re,highlights:ze,fixes:Be}})))()}var Ue,We,Ge,Ke,qe;function Je(){return(Je=e((()=>{Ue=`0.14.2`,We=`2026-11-02`,Ge=[{title:{en:`A faster agent panel`,zh:`更快的智能体面板`},body:{en:`The agent panel now starts Claude before you send your first message, keeps open threads running while they sit idle, and no longer waits for Overleaf comments to refresh before sending. A new thread answers about 2 seconds sooner, and a reply after a pause comes in about half the time. Claude is now the panel's default agent.`,zh:`智能体面板现在会在你发送第一条消息前就启动 Claude，打开的对话在空闲时也会保持运行，发送消息时也不再等待 Overleaf 评论刷新。新对话的首次回答快了约 2 秒，停顿后的回复用时约减半。Claude 现在是面板的默认智能体。`}},{title:{en:`Your own MCP servers are off in the panel by default`,zh:`面板默认不再加载你自己的 MCP 服务器`},body:{en:`The agent panel now loads only Lattice's own tools, which is part of what makes it start faster. If you use your own MCP servers with Claude, turn on Load my MCP servers in Claude in Settings to bring them back.`,zh:`智能体面板现在只加载 Lattice 自带的工具，这也是它启动更快的原因之一。如果你在 Claude 中使用自己的 MCP 服务器，请在设置中打开“Load my MCP servers in Claude”（在 Claude 中加载我的 MCP 服务器）以恢复它们。`}}],Ke=[{en:`A new chat can use Lattice's tools, such as showing a visual, from its first message.`,zh:`新对话从第一条消息起就能使用 Lattice 的工具，例如显示可视化内容。`},{en:`The effort level shown in the agent panel is now the one actually sent to the agent.`,zh:`智能体面板中显示的推理强度现在就是实际发送给智能体的强度。`}],qe={version:Ue,date:We,highlights:Ge,fixes:Ke}})))()}var Ye,Xe,Ze,Qe,$e;function et(){return(et=e((()=>{Ye=`0.14.3`,Xe=`2026-11-02`,Ze=[],Qe=[{en:`An open file that is deleted or renamed outside Lattice no longer becomes a tab that never saves: the tab follows a renamed file, closes when nothing is unsaved, or keeps your edits and offers to recreate or save them elsewhere. Restoring an older version of the file now reloads it.`,zh:`在 Lattice 之外删除或重命名的已打开文件，不会再变成一个永远无法保存的标签页：文件被重命名时标签页会跟随它；没有未保存内容时标签页会关闭；有未保存的编辑时会保留它们，并提供重新创建或另存为的选项。恢复该文件的旧版本后也会重新载入。`},{en:`⌘Z in the source editor undoes only your own typing, not an Overleaf collaborator's or the agent's edits.`,zh:`源码编辑器中的 ⌘Z 现在只撤销你自己的输入，不会撤销 Overleaf 协作者或智能体的编辑。`},{en:`A project's or your own .latexmkrc can no longer move the PDF out of the preview or keep a build from finishing.`,zh:`项目中或你自己的 .latexmkrc 不再能把 PDF 移出预览，也不会让编译一直无法结束。`},{en:`\\input and \\include paths now resolve from the root document's folder, so a root in a subfolder finds its files.`,zh:`\\input 和 \\include 的路径现在从主文档所在的文件夹解析，因此位于子文件夹中的主文档也能找到它的文件。`},{en:`Building a standalone figure or a subfiles chapter compiles it once and no longer makes it the project's main document.`,zh:`编译 standalone 图形或 subfiles 章节时只会编译它一次，不再把它设为项目的主文档。`},{en:`A .bib file linked from outside the project, such as a Zotero export, now works with citations, search and replace.`,zh:`从项目外部链接进来的 .bib 文件（例如 Zotero 导出的文件）现在可以正常用于引用、搜索和替换。`},{en:`Enter and Escape in the symbol palette, find and replace, and file rename are left to your input method while it is composing.`,zh:`在符号面板、查找替换和文件重命名中，输入法正在输入时，Enter 和 Escape 会交给输入法处理。`},{en:`Settings stay in sync across open windows, and the "Your name" setting keeps the spaces you type.`,zh:`设置会在所有打开的窗口之间保持同步，“你的名字”设置也会保留你输入的空格。`},{en:`A hidden agent panel no longer keeps Claude running or warms up new chats.`,zh:`隐藏的智能体面板不再让 Claude 保持运行，也不再预热新对话。`},{en:`Claude in the agent panel can now pick Lattice's enabled bundled skills, such as making slides, on its own.`,zh:`智能体面板中的 Claude 现在能自行选用 Lattice 已启用的内置技能，例如制作幻灯片。`},{en:`The remaining error messages from the app now show in Chinese in the Chinese interface.`,zh:`中文界面中，剩余的应用错误信息现在也会以中文显示。`},{en:`The PDF viewer is updated to pdf.js 6.5.438.`,zh:`PDF 查看器已更新到 pdf.js 6.5.438。`}],$e={version:Ye,date:Xe,highlights:Ze,fixes:Qe}})))()}var tt,nt,rt,it,at;function ot(){return(ot=e((()=>{tt=`0.15.0`,nt=`2026-11-03`,rt=[{title:{en:`Synara 1.1.0 in the Agent panel`,zh:`智能体面板升级到 Synara 1.1.0`},body:{en:`The Agent panel is updated to Synara 1.1.0 and follows Lattice's language, with its Chinese now drawn from Synara's own translations. A new "Resume after usage limits" setting is off by default, and quitting Lattice mid-reply no longer makes the agent carry on by itself on the next launch.`,zh:`智能体面板已升级到 Synara 1.1.0，并跟随 Lattice 的界面语言，中文译文现在主要来自 Synara 自身。新增“用量限额重置后继续”设置，默认关闭；在回复中途退出 Lattice 后，下次启动时智能体也不会再自行继续。`}},{title:{en:`The app moves more fluidly`,zh:`应用动效更流畅`},body:{en:`Menus and popups spring in, the Polish card unrolls and its edits arrive in turn, Accept strikes the old words and settles the new ones, lines the agent writes into an open file briefly wash green, new Overleaf comment threads ring as they arrive, switching files and views fades, and paper counts roll. Everything settles at once with Reduce Motion on.`,zh:`菜单和弹出框会弹性出现，润色卡片会向下展开，修改逐条呈现；接受修改时旧文字被划去，新文字随之落定；智能体写入已打开文件的行会短暂泛绿；新的 Overleaf 评论线程出现时会有一圈提示；切换文件和视图时会淡入，论文计数会滚动变化。开启“减少动态效果”后，一切都会立即落定。`}}],it=[{en:`Pasting an arXiv:<id> such as arXiv:1706.03762 into Add papers, or importing one, now finds the paper instead of failing after a long title search.`,zh:`在“添加论文”中粘贴或导入 arXiv:<id>（例如 arXiv:1706.03762）现在能找到对应论文，不会在漫长的标题搜索后失败。`}],at={version:tt,date:nt,highlights:rt,fixes:it}})))()}var st,ct,lt,ut,dt;function ft(){return(ft=e((()=>{st=`0.15.1`,ct=`2026-11-04`,lt=[{title:{en:`A new app icon`,zh:`全新的应用图标`},body:{en:`Lattice's icon is now olive on cream.`,zh:`Lattice 的图标换成了奶油底色上的橄榄绿。`}},{title:{en:`Try Lattice in your browser`,zh:`在浏览器中试用 Lattice`},body:{en:`The website now has a live demo of the real Lattice workspace at https://leo1oel.github.io/lattice/demo/, so you can try it before you download.`,zh:`网站上新增了真实 Lattice 工作区的在线演示（https://leo1oel.github.io/lattice/demo/），下载前即可先试用。`}}],ut=[],dt={version:st,date:ct,highlights:lt,fixes:ut}})))()}var pt,mt,ht,gt,_t;function vt(){return(vt=e((()=>{pt=`0.15.2`,mt=`2026-11-04`,ht=[{title:{en:`Math preview above the formula`,zh:`公式预览移到公式上方`},body:{en:`The live preview of the formula you are editing now appears just above it, so it no longer covers the lines below.`,zh:`正在编辑的公式的实时预览现在显示在它的正上方，不再遮住下面的内容。`}},{title:{en:`Annotations land on the right words`,zh:`批注落在正确的文字上`},body:{en:`A note's mark on the PDF now covers the same words as its source, its pin sits in the margin, the empty list is a centred drawing, and the toolbar shows the note count beside its icon.`,zh:`PDF 上的批注标记现在覆盖与源文件相同的文字，图钉移到页边，空列表显示为居中的插图，工具栏在图标旁显示批注数量。`}},{title:{en:`Nothing covers your work`,zh:`不再遮挡你的内容`},body:{en:`The Proofread card scrolls into view, after a successful build the Build panel docks under the PDF instead of floating over it, Overleaf collaborators' names show briefly instead of always, and actions that need a selection say so.`,zh:`校对卡片会自动滚动到可见位置，编译成功后编译面板会停靠在 PDF 下方而不是浮在上面，Overleaf 协作者的名字只短暂显示，需要先选中文字的操作也会给出提示。`}}],gt=[{en:`"Save and revise now" revises only the note it saves.`,zh:`“保存并立即修改”现在只修改它保存的那条批注。`},{en:`Opening a sheet no longer rewrites the file or adds an edit to History.`,zh:`打开表格不再改写文件，也不会在历史中留下一条编辑记录。`},{en:`⇧-click Build cleans the project before building again.`,zh:`⇧-点击“编译”会先清理项目再重新编译。`},{en:`Jumping between the PDF and the source keeps working after the project folder moves.`,zh:`项目文件夹移动后，PDF 与源文件之间的跳转仍然可用。`},{en:`Borders and focus rings are no longer cut off at the edge of a scrolling list, the titlebar starts at the edge when the window lights are hidden, and the Build button is centred.`,zh:`边框和焦点环不再在滚动列表的边缘被截断，隐藏窗口按钮时标题栏从最左侧开始，“编译”按钮也居中了。`},{en:`Tabs, setup, the command palette, Check references, History, Annotations and dialogs are tidier, and lists use quieter punctuation that follows your language.`,zh:`标签页、安装引导、命令面板、检查引用、历史、批注和各个对话框更整洁，列表改用更安静、随界面语言变化的标点。`},{en:`The browser demo shows Overleaf, Add papers, History, Versions and Rewrite honestly, and its narrow dark page is fixed.`,zh:`浏览器演示如实呈现 Overleaf、添加论文、历史、版本和改写功能，窄屏深色页面的问题也已修复。`},{en:`The app starts with less code to load.`,zh:`应用启动时需要加载的代码更少了。`}],_t={version:pt,date:mt,highlights:ht,fixes:gt}})))()}var yt,bt,xt,St,Ct;function wt(){return(wt=e((()=>{yt=`0.15.3`,bt=`2026-11-05`,xt=[{title:{en:`Code files in your project`,zh:`项目中的代码文件`},body:{en:`Python and common code and configuration files (JavaScript, Rust, Go, C and C++, Java, Ruby, R, shell scripts, JSON, YAML, TOML, XML, CSS, SQL and more) can be created, dropped in, searched and attached to the agent, and their editors offer autocompletion.`,zh:`Python 以及常见的代码和配置文件（JavaScript、Rust、Go、C 和 C++、Java、Ruby、R、Shell 脚本、JSON、YAML、TOML、XML、CSS、SQL 等）现在可以新建、拖入、搜索并附加给 AI 助手，编辑这些文件时还有自动补全。`}},{title:{en:`Switch Overleaf accounts`,zh:`切换 Overleaf 账号`},body:{en:`After signing out you can sign in with a different account. Sign out and Cancel now really end a sign-in in progress, and ⌘Z and ⇧⌘Z work in the sign-in window.`,zh:`退出登录后可以换一个账号重新登录。“退出登录”和“取消”现在会真正结束正在进行的登录，登录窗口中也能使用 ⌘Z 和 ⇧⌘Z。`}},{title:{en:`The agent panel remembers your setup`,zh:`AI 助手面板记住你的设置`},body:{en:`Your default provider, model, effort, hidden providers, provider order and drafts are kept across launches, and Settings → Agent providers has a Default provider row.`,zh:`默认提供商、模型、推理强度、隐藏的提供商、提供商顺序和草稿在重新启动后都会保留，“设置 → AI 助手 → 模型”页面新增了“默认提供商”一行。`}}],St=[{en:`Hovering a command inside a formula no longer opens its description over the live math preview.`,zh:`在公式中悬停命令时，不再在实时数学预览上方弹出命令说明。`},{en:`Versions shows the right timeline and restores correctly for a project inside a larger Git repository, and a refused restore no longer leaves a stray auto-saved version.`,zh:`位于更大 Git 仓库中的项目，其版本时间线和恢复操作现在都正确无误；被拒绝的恢复也不再留下多余的自动保存版本。`},{en:`Zoomed panels stay on screen in narrow windows.`,zh:`在较窄的窗口中，放大的面板会保持在屏幕内。`},{en:`The terminal no longer freezes on heavy output when it opens.`,zh:`终端打开时遇到大量输出不再卡住。`},{en:`A pipe or other special file ending in .pdf no longer stalls PDF reading.`,zh:`以 .pdf 结尾的管道或其他特殊文件不再导致 PDF 读取卡住。`},{en:`Literature search no longer answers from an out-of-date index after two searches clash.`,zh:`两次搜索冲突后，文献搜索不再使用过期的索引作答。`},{en:`The app starts with a little less code to load.`,zh:`应用启动时需要加载的代码又少了一些。`}],Ct={version:yt,date:bt,highlights:xt,fixes:St}})))()}var Tt,Et,Dt,Ot,kt;function At(){return(At=e((()=>{Tt=`0.15.4`,Et=`2026-11-05`,Dt=[{title:{en:`Notes from the .tex on the PDF`,zh:`在 PDF 上显示 .tex 中的批注`},body:{en:`Annotations made in a .tex file now also show on the PDF, on the words they belong to, with the same marks, pins and cards as notes made on the PDF.`,zh:`在 .tex 文件中添加的批注现在也会显示在 PDF 上，落在对应的文字处，标记、图钉和卡片都与在 PDF 上添加的批注一致。`}}],Ot=[{en:`Marks on the PDF follow their words after a rebuild that changes only some pages.`,zh:`重新编译只改动了部分页面时，PDF 上的标记仍会跟随对应的文字。`},{en:`Choosing Select All from the menu and then typing now always replaces everything.`,zh:`从菜单选择“全选”后再输入，现在总能替换全部内容。`},{en:`The in-browser demo opens PNG figures as images, loads images in Markdown notes, shows a placeholder while it starts, and explains that Source control runs in the Mac app instead of showing an error.`,zh:`浏览器在线演示现在会把 PNG 图片显示为图像、能加载 Markdown 笔记中的图片、启动时显示占位画面，并说明 Git 功能需在 Mac 应用中使用，而不再报错。`},{en:`The README links the browser demo and the release notes, and the project now has a code of conduct.`,zh:`README 新增了浏览器在线演示和更新说明的链接，项目也有了行为准则。`}],kt={version:Tt,date:Et,highlights:Dt,fixes:Ot}})))()}var jt,Mt,Nt,Pt,Ft;function It(){return(It=e((()=>{jt=`0.15.5`,Mt=`2026-11-06`,Nt=[{title:{en:`Every Overleaf project you can open`,zh:`显示你能打开的所有 Overleaf 项目`},body:{en:`The import list shows all your Overleaf projects in Overleaf's own order with each owner, plus invitations you have not accepted yet, with Open invitation. You can also paste an Overleaf project or share link to open it, and you are told clearly when it needs joining, an accepted invitation or access.`,zh:`导入列表会按 Overleaf 自己的顺序列出你的所有 Overleaf 项目并注明每个项目的所有者，还会列出你尚未接受的邀请，可点“打开邀请”。你也可以粘贴 Overleaf 项目链接或分享链接来打开项目；如果需要先加入项目、接受邀请或获得访问权限，会明确告诉你。`}},{title:{en:`The AI assistant says what went wrong`,zh:`AI 助手会说明出了什么问题`},body:{en:`When Claude Code cannot start, the card says why and what to do, such as updating a Claude Code older than 2.0.63 or signing in. A model your account cannot use is greyed out with the reason, and the composer switches to the default model with a notice. An Anthropic 403 refusal gets its own message, and warnings show next to the composer.`,zh:`Claude Code 无法启动时，卡片会说明原因和解决办法，例如更新低于 2.0.63 的 Claude Code 或先登录。你的账号无法使用的模型会显示为灰色并注明原因，输入框会切换到默认模型并给出提示。Anthropic 的 403 拒绝有单独的提示，警告也会显示在输入框旁边。`}},{title:{en:`No more repeated login keychain prompts`,zh:`不再反复请求访问登录钥匙串`},body:{en:`Lattice no longer asks for the login keychain over and over. A denied or unanswered prompt is remembered, and Settings > Agent > Usage & limits has a Refresh button to try again.`,zh:`Lattice 不再一遍又一遍地请求访问登录钥匙串。被拒绝或未响应的请求会被记住；如需重试，可在“设置 > AI 助手 > 用量与限制”中点“刷新”。`}}],Pt=[{en:`The Overleaf sign-in window has a Back to Overleaf sign-in button on Google, ORCID, IEEE and SSO pages.`,zh:`Overleaf 登录窗口在 Google、ORCID、IEEE 和 SSO 页面上提供“返回 Overleaf 登录”按钮。`},{en:`Check references proposes references and field names in English in any interface language, no longer sticks the tag to the next word, no longer proposes braces around a whole title, and no longer names an undated paper NIPS. A note says that closing the window does not stop the check.`,zh:`“检查引用”在任何界面语言下都用英文给出建议的参考文献和字段名，标签不再与后面的单词粘在一起，不再建议给整个标题加花括号，也不再把没有年份的论文命名为 NIPS。另有提示说明关闭窗口不会停止检查。`},{en:`Annotation pins on the PDF match the size of the source gutter's pins and scale with the zoom.`,zh:`PDF 上的批注图钉与源码边栏中的图钉大小一致，并会随缩放变化。`},{en:`The editor runs on Tiptap 3.33.0, and presentations on the latest Open Slide.`,zh:`编辑器升级到 Tiptap 3.33.0，演示文稿使用最新版 Open Slide。`},{en:`Developer builds give the performance lab its own test keychain.`,zh:`开发版为性能测试环境提供独立的测试钥匙串。`}],Ft={version:jt,date:Mt,highlights:Nt,fixes:Pt}})))()}var Lt,Rt,zt,Bt,Vt;function Ht(){return(Ht=e((()=>{Lt=`0.15.6`,Rt=`2026-11-07`,zt=[{title:{en:`Overleaf projects open after the main file is renamed`,zh:`Overleaf 主文件改名后项目仍能打开`},body:{en:`A project whose main file was renamed on Overleaf, for example from main.tex to main_v2.tex, opens again instead of showing "No such file or directory". Right-click a .tex file and choose Set as main document to pick what is built, and your choice always decides. In Overleaf-linked projects you can select text in the PDF and post an Overleaf comment on the matching source.`,zh:`主文件在 Overleaf 上改过名的项目（例如从 main.tex 改为 main_v2.tex）现在能正常打开，不再显示“No such file or directory”。右键点击 .tex 文件并选择“设为主文档”即可决定编译哪个文件，并且始终以你的选择为准。在关联 Overleaf 的项目中，你可以在 PDF 中选中文字，在对应的源码上发表 Overleaf 评论。`}},{title:{en:`The AI assistant never deletes a reference on its own`,zh:`AI 助手不会擅自删除参考文献`},body:{en:`It asks you before removing a .bib entry. Removing an entry no longer reformats the others, which used to lose fields such as volume and pages, and after an edit Check references checks only the entries that changed.`,zh:`删除 .bib 条目前，AI 助手会先询问你。删除一个条目不再会重新格式化其他条目（以前会丢失 volume、pages 等字段），编辑之后“检查引用”只会重新检查改动过的条目。`}},{title:{en:`A .bib file's Split view stays in step`,zh:`并排查看 .bib 文件时两边保持同步`},body:{en:`The source and the reference list follow each other both ways, and each reference offers Open paper or Download and open.`,zh:`源码和参考文献列表会双向同步，每条参考文献都提供“打开论文”或“下载并打开”。`}},{title:{en:`Project actions in the File menu`,zh:`项目操作进入“文件”菜单`},body:{en:`The macOS File menu has New Project (⇧⌘N), Open, Open Recent, Open from Overleaf, Import Overleaf ZIP, Export ZIP and Export for arXiv, the same actions as the project title menu.`,zh:`macOS 的“文件”菜单新增“新建项目”（⇧⌘N）、“打开”、“打开最近使用”、“从 Overleaf 打开”、“导入 Overleaf ZIP”、“导出 ZIP”和“导出 arXiv 提交包”，与项目标题菜单中的操作相同。`}}],Bt=[{en:`Clicking the paper title on a citation card opens the paper, or its .bib entry, and Open paper is back on the card.`,zh:`点击引用卡片上的论文标题会打开该论文（或它的 .bib 条目），卡片上的“打开论文”也回来了。`},{en:`A paper opens on its full text, at the top, the first time you open it.`,zh:`第一次打开论文时，会显示全文并从顶部开始。`},{en:`Margin review's On screen list is now called In view, with a tooltip saying what it lists.`,zh:`页边审阅中的“这一屏”列表改名为“当前可见”，并有提示说明其中列出的内容。`},{en:`History > Compare > Export PDF with changes no longer runs latexdiff without end. It stops after a time or memory limit, Cancel works while it runs, closing the comparison or quitting Lattice stops it, and files that read each other with \\input are named in a clear message.`,zh:`“历史 > 对比 > 导出修改对照 PDF”不会再让 latexdiff 无休止地运行。超过时间或内存上限时会停止；运行期间可以点“取消”，关闭对比或退出 Lattice 也会停止它；如果文件之间用 \\input 互相读入，会给出明确提示并指出是哪些文件。`}],Vt={version:Lt,date:Rt,highlights:zt,fixes:Bt}})))()}var Ut,Wt,Gt,Kt,qt;function Jt(){return(Jt=e((()=>{Ut=`0.15.7`,Wt=`2026-11-07`,Gt=[{title:{en:`A Get started checklist replaces the guided tour`,zh:`“上手”清单取代引导教程`},body:{en:`Six steps walk you through Lattice: install LaTeX, build the sample paper, jump between the PDF and the source, cite a paper, let the AI assistant revise a paragraph, and start your own paper. Each step says in one sentence why it matters and has Show me and Skip, and your progress is kept. Setting up LaTeX is now one of the steps instead of a popup. The checklist opens on first launch and in the web demo.`,zh:`六个步骤带你熟悉 Lattice：安装 LaTeX、编译示例论文、在 PDF 和源码间跳转、引用一篇论文、让 AI 助手改一段文字，以及开始写你自己的论文。每一步都用一句话说明为什么要做，并提供“指给我看”和“跳过”，进度会自动保存。安装 LaTeX 现在是清单中的一步，不再弹窗提示。首次启动和网页演示中都会自动打开这份清单。`}},{title:{en:`The AI assistant finds Claude Code and Codex more reliably`,zh:`AI 助手更容易找到 Claude Code 和 Codex`},body:{en:`It looks in their usual install folders even when your shell's PATH misses them, and checks again without a restart. When it finds neither, it says which agents are supported and how to install one and sign in, with Set path… and Check again.`,zh:`即使终端的 PATH 里没有它们，AI 助手也会到常见的安装位置查找，并且无需重启就能重新检测。如果一个都没找到，它会说明支持哪些工具、如何安装并登录，并提供“设置路径…”和“重新检查”。`}}],Kt=[{en:`The app icon follows Apple's macOS icon grid, so it is the same size as the other apps in the Dock.`,zh:`应用图标改用 Apple 的 macOS 图标网格绘制，在程序坞里和其他应用一样大。`}],qt={version:Ut,date:Wt,highlights:Gt,fixes:Kt}})))()}var Yt,Xt,Zt,Qt,$t;function en(){return(en=e((()=>{Yt=`0.15.8`,Xt=`2026-11-07`,Zt=[{title:{en:`Lattice for Linux (experimental)`,zh:`Lattice 支持 Linux（实验性）`},body:{en:`Each release now includes an x86_64 AppImage, tested on Ubuntu 22.04 and 24.04 and Fedora. You need a TeX distribution installed. The AI assistant is off on Linux for now, and the app does not update itself there: download new versions from the release page. Thanks to Stefan Bringuier for the first Linux port.`,zh:`每个版本现在都附带 x86_64 AppImage，已在 Ubuntu 22.04、24.04 和 Fedora 上测试。需要先安装 TeX 发行版。Linux 上暂时关闭了 AI 助手，应用也不会自动更新：新版本请到发布页面下载。感谢 Stefan Bringuier 完成最初的 Linux 移植。`}},{title:{en:`The AI assistant can continue your other Claude Code and Codex sessions`,zh:`AI 助手可以继续你在别处的 Claude Code 和 Codex 会话`},body:{en:`Its history menu now lists the sessions you started for the open folder in VS Code or the terminal, and you can pick one up where you left off.`,zh:`历史菜单现在会列出你在 VS Code 或终端里为当前文件夹开启的会话，选中即可从上次停下的地方继续。`}}],Qt=[{en:`⌘-scroll zooms the PDF, and pinching over the PDF no longer zooms the whole workspace.`,zh:`⌘ + 滚动可以缩放 PDF，在 PDF 上双指捏合也不会再缩放整个工作区。`},{en:`Overleaf: a full sync no longer stops you from creating or deleting files, a stalled download retries, and the download shows its progress.`,zh:`Overleaf：完整同步时也能新建和删除文件，下载卡住时会自动重试，并显示下载进度。`},{en:`Opening an Overleaf project that a local folder already links opens that folder instead of downloading a second copy.`,zh:`打开一个已经关联到本地文件夹的 Overleaf 项目时，会直接打开那个文件夹，不再重复下载一份。`},{en:`The AI assistant's prompt box stays inside a short panel while you type a long prompt.`,zh:`在较矮的面板里输入长提示词时，AI 助手的输入框不会再超出面板。`},{en:`The AI assistant's rate-limit notice keeps its close button on the first line, reads fully in your language, and shows reset times you can read at a glance.`,zh:`AI 助手的用量限制提示把关闭按钮保持在第一行，全部内容都用你的语言显示，重置时间也一目了然。`}],$t={version:Yt,date:Xt,highlights:Zt,fixes:Qt}})))()}var tn,nn,rn,an,on;function sn(){return(sn=e((()=>{tn=`0.16.1`,nn=`2026-11-09`,rn=[{icon:`plug`,title:{en:`Import papers from Zotero`,zh:`从 Zotero 导入论文`},body:{en:`Add papers can now browse your Zotero library, including its collections and sub-collections, and bring in the papers you pick.`,zh:`“添加论文”现在可以浏览你的 Zotero 文献库，包括其中的分类和子分类，并导入你选中的论文。`}},{icon:`git`,title:{en:`Safer, faster Overleaf collaboration`,zh:`Overleaf 协作更安全、更快`},body:{en:`Your co-authors' edits survive conflict saves, remote deletes and restores. Typing at the same time as a co-author stays in live editing instead of falling back to a full sync, and Lattice sends its sync edits to Overleaf as live edits too. Syncing fetches only the files that changed instead of the whole project, and a co-author's live typing no longer rebuilds the PDF on every keystroke.`,zh:`保存冲突、远端删除和恢复文件时，合作者的修改都会保留。和合作者同时输入时会继续保持实时编辑，不再退回完整同步；Lattice 同步的修改也会以实时编辑的方式发送到 Overleaf。同步时只获取有改动的文件，不再下载整个项目；合作者实时输入时，也不会每敲一个键就重新编译一次 PDF。`}},{icon:`message`,title:{en:`Review comments beside the PDF`,zh:`在 PDF 旁查看评论`},body:{en:`Read and answer comments in a column next to the PDF, and comment on a PDF passage from any source file in one step.`,zh:`在 PDF 旁边的一栏里阅读和回复评论；无论打开的是哪个源文件，都能一步给 PDF 中的段落添加评论。`}},{icon:`undo`,title:{en:`Review history with tracked changes`,zh:`用修订模式审阅历史`},body:{en:`A review mode in History shows changes as tracked edits you can accept or reject, with the changes marked in the PDF.`,zh:`历史记录新增审阅模式：改动以修订的形式显示，可以逐条接受或拒绝，PDF 中也会标出这些改动。`}},{icon:`feather`,title:{en:`Better citations`,zh:`更好用的引用`},body:{en:`Notes link to the exact page of the cited paper, and you can add an optional "why I cited this" reason to each citation.`,zh:`笔记会链接到被引论文的具体页码；每处引用还可以选择写下“为什么引用它”的理由。`}},{icon:`menu`,title:{en:`More ways to set up and write`,zh:`更多设置与写作方式`},body:{en:`Choose the font, size and line height of the source and Markdown editors in Settings, clone a Git repository into a new project, and use Vim's :w, :q and :wq. There is also a new CVPR 2027 Rebuttal template.`,zh:`可以在设置中选择源码编辑器和 Markdown 编辑器的字体、字号与行高；可以把 Git 仓库克隆为新项目；Vim 的 :w、:q 和 :wq 也能用了。另外新增了 CVPR 2027 Rebuttal 模板。`}},{title:{en:`Lattice for Intel-based Macs`,zh:`Lattice 支持 Intel-based Mac`},body:{en:`Each release now includes a signed, notarized Intel (x64) Mac build.`,zh:`每个版本现在都附带经过签名和公证的 Intel（x64）Mac 版本。`}}],an=[{en:`Undoing an AI assistant edit keeps your co-authors' edits, and turns overlapping changes into conflicts instead of overwriting them.`,zh:`撤销 AI 助手的修改时会保留合作者的修改；有重叠的改动会标记为冲突，而不会被覆盖。`},{en:`Annotations and bibliography edits are never saved over stale or unread text, and an audit of hidden state bugs fixed more cases like it.`,zh:`批注和参考文献的修改不会再覆盖过时或尚未读取的内容；一次针对隐藏状态问题的排查还修复了更多类似情况。`},{en:`Overleaf reconnect, switching projects, stopping a build, Fix all and reloading the AI assistant panel no longer get stuck.`,zh:`Overleaf 重新连接、切换项目、停止编译、“一键修复”以及重新加载 AI 助手面板时不会再卡住。`},{en:`Format document results and Overleaf's rejected edits stay tied to the right text.`,zh:`“整理排版”的结果和被 Overleaf 拒绝的修改会对应到正确的文本。`},{en:`Files that still have conflict markers are not merged again, and fallback uploads to Overleaf are checked against their own history.`,zh:`仍带有冲突标记的文件不会再被重复合并；向 Overleaf 的备用上传会对照它自己的历史进行校验。`},{en:`Bibliography upgrades apply entry by entry instead of tidying the whole file.`,zh:`参考文献升级会逐条应用，不再整理整个文件。`},{en:`A citation card under a comment stays reachable.`,zh:`被评论遮住的引用卡片现在也能点到。`},{en:`Citation suggestions stay open while you backspace through keys. Thanks to @ajay-mk.`,zh:`用退格键删除引用键时，引用建议会保持显示。感谢 @ajay-mk。`},{en:`The AI assistant explains when your Codex is too old to list GPT-6 Astra.`,zh:`Codex 版本太旧、无法列出 GPT-6 Astra 时，AI 助手会说明原因。`},{en:`Linux users are told when a new release is out. Thanks to @knightnemo.`,zh:`有新版本发布时会通知 Linux 用户。感谢 @knightnemo。`},{en:`The empty annotations panel is redrawn without "Return to file", the Git drawer's empty states are centred, and the in-app Lattice mark uses the icon's olive and sage.`,zh:`空的批注面板重新设计，去掉了“返回文件”；Git 抽屉的空状态改为居中显示；应用内的 Lattice 标志改用图标的橄榄绿和鼠尾草绿。`},{en:`Developers: steadier perf-bench startup and Linux AppImage end-to-end tests.`,zh:`开发者：perf-bench 启动和 Linux AppImage 端到端测试更稳定。`}],on={version:tn,date:nn,highlights:rn,fixes:an}})))()}var cn,ln,un,dn,fn;function pn(){return(pn=e((()=>{cn=`0.16.10`,ln=`2026-11-10`,un=[{title:{en:`Spell checking in your document's language`,zh:`按文档语言检查拼写`},body:{en:`Lattice reads the document language from babel or polyglossia. Other languages get spell checking with a dictionary downloaded on first use; English keeps spelling and grammar checks. Thanks to @quark67.`,zh:`Lattice 会从 babel 或 polyglossia 读取文档语言。其他语言首次使用时会下载词典并检查拼写；英文仍同时检查拼写和语法。感谢 @quark67。`}},{title:{en:`New project templates`,zh:`新增项目模板`},body:{en:`IEEE conference, IEEE journal and ACM (acmart).`,zh:`新增 IEEE 会议、IEEE 期刊和 ACM（acmart）模板。`}},{title:{en:`Experimental Windows installer`,zh:`实验性 Windows 安装包`},body:{en:`Each release now includes an unsigned Windows x64 installer. It is experimental; read docs/windows-installer.md in the Lattice repository before installing. Thanks to @LucasDavidTPE.`,zh:`每个版本现在都附带未签名的 Windows x64 安装包。该安装包仍处于实验阶段，安装前请先阅读 Lattice 仓库中的 docs/windows-installer.md。感谢 @LucasDavidTPE。`}}],dn=[{en:`"Install missing package" no longer gives up when several TeX Live packages provide the same file (such as IEEEtran.cls); Lattice lets you choose which one to install.`,zh:`多个 TeX Live 包提供同一文件（如 IEEEtran.cls）时，“安装缺失的包”不再直接放弃，而是让你选择要安装的包。`},{en:`Lower idle CPU use: no always-running animations, Overleaf checks pause while the window is hidden, and continuous file writes trigger fewer full project rescans.`,zh:`降低空闲时的 CPU 占用：不再有持续运行的动画，窗口隐藏时暂停 Overleaf 检查，连续写入文件时减少整个项目的重新扫描。`},{en:`About Lattice and the Help menu link to the GitHub repository and the website. Thanks to @quark67.`,zh:`“关于 Lattice”和帮助菜单中加入了 GitHub 仓库和官网的链接。感谢 @quark67。`},{en:`On Windows, the Overleaf sign-in window no longer opens blank. Thanks to @ivanvykopal.`,zh:`在 Windows 上，Overleaf 登录窗口不再显示空白。感谢 @ivanvykopal。`}],fn={version:cn,date:ln,highlights:un,fixes:dn}})))()}var mn,hn,gn,_n,vn;function yn(){return(yn=e((()=>{mn=`0.16.11`,hn=`2026-11-10`,gn=[{title:{en:`Much lower idle CPU and energy use`,zh:`大幅降低空闲时的 CPU 和能耗`},body:{en:`The Agent panel no longer runs a hidden per-frame loop. It caused about 90% of Lattice's idle CPU use and most of its background wakeups, even when the panel was hidden.`,zh:`AI 助手面板不再在后台运行逐帧循环。即使面板处于隐藏状态，它也曾占用 Lattice 约 90% 的空闲 CPU，并造成大部分后台唤醒。`}},{title:{en:`Agent tasks use a provider you have connected`,zh:`AI 助手任务使用你已连接的服务`},body:{en:`Proofreading, polishing, compile repair and Git commit messages use whichever AI provider you have connected, right after launch. Claude-only setups no longer see "Codex CLI is required".`,zh:`校对、润色、编译修复和 Git 提交信息会使用你已连接的 AI 服务，启动后即可使用。只连接了 Claude 的用户不会再看到“需要 Codex CLI”。`}},{title:{en:`Continue in terminal`,zh:`在终端中继续`},body:{en:`The Agent can copy a command that continues the current chat in Codex CLI or Claude Code.`,zh:`AI 助手可以复制一条命令，在 Codex CLI 或 Claude Code 中继续当前对话。`}}],_n=[{en:`Each compiled document keeps its own PDF tab. Thanks to @surajinacademia.`,zh:`每个编译的文档都保留自己的 PDF 标签页。感谢 @surajinacademia。`},{en:`Markdown comments use a lighter highlight, and the comment box closes when you click outside it or press Escape, keeping your text.`,zh:`Markdown 批注的高亮更浅；点击外部或按 Escape 会关闭批注框，并保留已输入的文字。`},{en:`Commenting works right after the Agent edits a file in an Overleaf-linked project.`,zh:`在关联 Overleaf 的项目中，AI 助手编辑文件后可以立即添加批注。`},{en:`The error panel names the undefined command for documents in subfolders, says when the error list is capped, and says when an automatic repair left errors.`,zh:`对于子文件夹中的文档，错误面板会指出未定义的命令；错误列表被截断时会注明；自动修复后仍有错误时也会说明。`},{en:`When a newer version of Lattice may already fix a failure, Lattice tells you and offers an Update button.`,zh:`当新版 Lattice 可能已经修复某个失败时，Lattice 会提示你并提供“更新”按钮。`},{en:`The outline no longer covers the search panel's close button. Thanks to @BrianCyan.`,zh:`大纲不再遮挡搜索面板的关闭按钮。感谢 @BrianCyan。`},{en:`On Windows, Ctrl+wheel PDF zoom is gentler and middle-click autoscroll works. Thanks to @LucasDavidTPE.`,zh:`在 Windows 上，Ctrl+滚轮缩放 PDF 更平缓，并支持中键自动滚动。感谢 @LucasDavidTPE。`},{en:`Fixes to the Windows development setup. Thanks to @skytheacademic.`,zh:`修复了 Windows 开发环境配置的问题。感谢 @skytheacademic。`}],vn={version:mn,date:hn,highlights:gn,fixes:_n}})))()}var bn,xn,Sn,Cn,wn;function Tn(){return(Tn=e((()=>{bn=`0.16.2`,xn=`2026-11-09`,Sn=[{title:{en:`PDF preview in its own window`,zh:`在独立窗口中预览 PDF`},body:{en:`Open the compiled PDF in a separate window, for example on a second monitor, with SyncTeX working both ways between the source and that window.`,zh:`可以在单独的窗口中打开编译好的 PDF，比如放到第二台显示器上；源码和该窗口之间的 SyncTeX 双向跳转都可以使用。`}},{title:{en:`Keep TeX up to date`,zh:`让 TeX 保持最新`},body:{en:`New BasicTeX installs update their base packages, and the TeX doctor flags outdated packages with a one-click update.`,zh:`新安装的 BasicTeX 会更新基础宏包；TeX 诊断会标出过时的宏包，并提供一键更新。`}},{title:{en:`Steadier updates`,zh:`更新更稳定`},body:{en:`A brief download error (such as a 502 or a timeout) is retried, and if an update still fails you can try again or open the release page. Settings… (⌘,) and Check for Updates… are now in the Lattice menu, and Report a Problem… is in the Help menu.`,zh:`短暂的下载错误（如 502 或超时）会自动重试；如果更新仍然失败，可以重试或打开发布页面。“设置…”（⌘,）和“检查更新…”已加入 Lattice 菜单，“报告问题…”已加入帮助菜单。`}}],Cn=[{en:`CVPR review-mode line numbers are no longer drawn over the text.`,zh:`CVPR 审稿模式的行号不会再盖住正文。`},{en:`Accepting a citation suggestion after an unclosed \\cite{ keeps the rest of the line. Thanks to @ajay-mk.`,zh:`在未闭合的 \\cite{ 后接受引用建议时，会保留这一行的其余内容。感谢 @ajay-mk。`},{en:`In Add papers, the added paper's card keeps its borders, and a long citation key is shortened instead of overflowing.`,zh:`在“添加论文”中，已添加论文的卡片边框不再被裁掉，过长的引用键会被截断而不是溢出。`},{en:`Open Slide 2.3.2: slide thumbnails and the overview grid are left-aligned.`,zh:`Open Slide 2.3.2：幻灯片缩略图和概览网格改为左对齐。`}],wn={version:bn,date:xn,highlights:Sn,fixes:Cn}})))()}var En,Dn,On,kn,An;function jn(){return(jn=e((()=>{En=`0.16.3`,Dn=`2026-11-09`,On=[{title:{en:`Git status no longer fills your repository`,zh:`Git 状态不再占满你的仓库`},body:{en:`The AI assistant's Git status summary uses a temporary object directory that is always removed, so it no longer writes into your repository's .git or leaves large temporary pack files behind after a timeout. Very large untracked files are skipped.`,zh:`AI 助手的 Git 状态摘要改用一个用完即删的临时对象目录，不再写入你仓库的 .git，也不会在超时后留下巨大的临时 pack 文件；特别大的未跟踪文件会被跳过。`}},{title:{en:`Check citations and Add papers agree`,zh:`“检查引用”与“添加论文”保持一致`},body:{en:`Both use one venue list, so entries added through Lattice pass Check citations unchanged. Venue names are no longer rewritten to forms like "Advances in Neural Information Processing Systems 35" or "Proceedings of the …", Findings venues (ACL, EMNLP, NAACL, …) are recognized with their abbreviations, and pasted, Zotero and editor entries get the same lookup as DOI imports.`,zh:`两者使用同一份会议列表，通过 Lattice 添加的条目无需修改即可通过“检查引用”。会议名称不再被改写成 “Advances in Neural Information Processing Systems 35” 或 “Proceedings of the …” 这样的形式；Findings 系列会议（ACL、EMNLP、NAACL 等）可按缩写识别；粘贴、Zotero 和编辑器中的条目与 DOI 导入使用相同的查询。`}},{title:{en:`Track changes builds for natbib papers again`,zh:`使用 natbib 的论文可以再次生成修订 PDF`},body:{en:`The PDF with changes marked builds again for natbib papers such as CVPR, ICLR and ACL templates. A change TeX can't mark is shown unmarked instead of losing the whole marked PDF.`,zh:`使用 natbib 的论文（如 CVPR、ICLR、ACL 模板）可以再次生成标出修改的 PDF。TeX 无法标记的修改会以未标记的形式显示，而不会导致整份标记 PDF 生成失败。`}}],kn=[{en:`PDF comments column: resize it by dragging its left edge; the close button no longer sits on the line, comments stack from the top, and the PDF's scrollbar no longer draws over the column.`,zh:`PDF 批注栏：拖动左边缘即可调整宽度；关闭按钮不再压在分隔线上，批注从顶部开始排列，PDF 的滚动条也不再盖住批注栏。`},{en:`Placing the caret in an already-written citation key shows only the hover card, without a suggestion list stacked under it, and the card's list of uses has Lattice's scrollbar.`,zh:`将光标放在已写好的引用键中时只显示悬停卡片，下面不再叠着建议列表；卡片中的引用位置列表使用 Lattice 的滚动条。`}],An={version:En,date:Dn,highlights:On,fixes:kn}})))()}var Mn,Nn,Pn,Fn,In;function Ln(){return(Ln=e((()=>{Mn=`0.16.4`,Nn=`2026-11-09`,Pn=[{title:{en:`Papers added through Lattice pass Check citations`,zh:`通过 Lattice 添加的论文能通过“检查引用”`},body:{en:`Add papers now runs the same lookup as Check citations, so it finds published versions known only to DBLP (ICLR, ICML, TMLR), Springer ECCV chapters and CVF paper pages. CVPR and ICCV pages from IEEE or CVF both count as correct. When the NeurIPS or ICLR proceedings sites can't be reached, the row is marked "official verification incomplete" instead of proposing changes, and an official link is never swapped for arXiv. Fixes are grouped into published version, formatting and sources differ, and Apply fixes leaves "sources differ" alone. Re-adding a paper you already cite offers Refresh entry.`,zh:`“添加论文”现在使用与“检查引用”相同的查询，能找到只有 DBLP 收录的正式发表版本（ICLR、ICML、TMLR）、Springer 的 ECCV 章节和 CVF 论文页面。来自 IEEE 或 CVF 的 CVPR、ICCV 页面都算正确。NeurIPS 或 ICLR 论文集网站无法访问时，该行会标为“官方核验未完成”，而不是提出修改，也绝不会把官方链接换成 arXiv。修改建议分为“正式发表版本”“格式”和“来源不一致”三组，“应用修改”会跳过“来源不一致”。重新添加已引用的论文时会提供“刷新条目”。`}},{title:{en:`A stuck TeX run is stopped`,zh:`卡住的 TeX 编译会被停止`},body:{en:`A build that makes no progress for 300 seconds, or repeats the same output for 120 seconds, is stopped and reports where it stood. Auto-build then waits for your next edit. Thanks to @Paivel.`,zh:`编译 300 秒没有进展，或 120 秒内一直重复相同输出时，会被停止并报告停在了哪里；之后自动编译会等你再次编辑。感谢 @Paivel。`}}],Fn=[{en:`Figure and \\input paths are resolved the way TeX does: no false "Missing figure" for ./ or ../ paths, and no stale copy picked from another folder. Thanks to @ajay-mk.`,zh:`图片和 \\input 路径按 TeX 的方式解析：./ 或 ../ 路径不再误报“缺少图片”，也不会选中其他文件夹里的旧副本。感谢 @ajay-mk。`},{en:`Groundwork for an experimental Windows build. There is no Windows download in this release. Thanks to @LucasDavidTPE.`,zh:`为实验性的 Windows 版本打下基础，本次发布不提供 Windows 下载。感谢 @LucasDavidTPE。`}],In={version:Mn,date:Nn,highlights:Pn,fixes:Fn}})))()}var Rn,zn,Bn,Vn,Hn;function Un(){return(Un=e((()=>{Rn=`0.16.5`,zn=`2026-11-09`,Bn=[{title:{en:`Figures you can edit in their drawing program`,zh:`可在绘图程序中编辑的图片`},body:{en:`Paste a figure from a drawing program and Lattice stores its source and rendered files in figures/, inserts the \\input and the packages it needs, and reopens the source in its program when you want to edit it. Drawings from Inkscape and draw.io (.svg, .drawio, .dio) become editable figures from the project tree, by paste or by drop, and re-render when the drawing changes: automatically in projects you trust, otherwise after you click Update figure. Thanks to @Paivel.`,zh:`从绘图程序粘贴图片时，Lattice 会把源文件和渲染结果存到 figures/，插入 \\input 和所需的宏包，需要编辑时会在原程序中重新打开源文件。来自 Inkscape 和 draw.io 的绘图（.svg、.drawio、.dio）可以通过项目树、粘贴或拖放成为可编辑图片，绘图改动后会重新渲染：在你信任的项目中自动进行，否则点击“更新插图”即可。感谢 @Paivel。`}},{title:{en:`chemnum compound numbers in the PDF and the editor`,zh:`PDF 和编辑器中的 chemnum 化合物编号`},body:{en:`Hovering a compound number in the PDF shows its key, and clicking copies \\cmpd{key}. Completion inside \\cmpd{ lists the project's compound keys with their numbers. Thanks to @Paivel.`,zh:`在 PDF 中悬停化合物编号会显示其键名，点击即可复制 \\cmpd{key}。在 \\cmpd{ 中补全会列出项目中的化合物键名及其编号。感谢 @Paivel。`}}],Vn=[{en:`A comment highlight has the same colour in the .tex source and in the PDF.`,zh:`批注高亮在 .tex 源文件和 PDF 中使用相同的颜色。`},{en:`A root document in a subfolder finds the bibliography and other files at the project root, as on Overleaf, so citations no longer show as [?].`,zh:`位于子文件夹中的主文档能找到项目根目录下的参考文献和其他文件（与 Overleaf 一致），引用不再显示为 [?]。`},{en:`When a build uses lineno 5.7, which draws CVPR review-mode line numbers over the text, Lattice says so and offers Update TeX packages. The TeX doctor checks for outdated packages once a day.`,zh:`编译使用 lineno 5.7（会把 CVPR 审稿模式的行号画在正文上）时，Lattice 会提示并提供“更新 TeX 组件”。TeX 诊断每天检查一次过时的宏包。`}],Hn={version:Rn,date:zn,highlights:Bn,fixes:Vn}})))()}var Wn,Gn,Kn,qn,Jn;function Yn(){return(Yn=e((()=>{Wn=`0.16.6`,Gn=`2026-11-09`,Kn=[{title:{en:`HTML and SVG in Markdown, drawn instead of shown as source`,zh:`Markdown 中的 HTML 和 SVG 直接绘制，不再显示源码`},body:{en:`Embedded HTML and inline SVG, such as a figure drafted as <svg>, show as a live, sanitized preview. Click it to edit the source, which is saved byte-for-byte.`,zh:`内嵌的 HTML 和行内 SVG（例如用 <svg> 绘制的图）会显示为经过清理的实时预览。点击即可编辑源码，保存时逐字节保留。`}}],qn=[{en:`The Markdown editor no longer drifts up or down while you read: images far above the view keep their size, and the editor holds your reading position.`,zh:`Markdown 编辑器在阅读时不再上下漂移：视图上方很远处的图片保持原有尺寸，编辑器会保持你的阅读位置。`},{en:`A Markdown table's header row stays with its table instead of sliding while you scroll.`,zh:`Markdown 表格的表头行在滚动时始终跟随表格，不再滑开。`},{en:`On Windows, the window stays maximized after you maximize it or close a file. Thanks to @ivanvykopal.`,zh:`在 Windows 上，最大化窗口或关闭文件后窗口保持最大化。感谢 @ivanvykopal。`},{en:`chemnum matches printed compound numbers faster and more safely.`,zh:`chemnum 匹配印刷的化合物编号更快、更安全。`}],Jn={version:Wn,date:Gn,highlights:Kn,fixes:qn}})))()}var Xn,Zn,Qn,$n,er;function tr(){return(tr=e((()=>{Xn=`0.16.7`,Zn=`2026-11-10`,Qn=[{title:{en:`Claude Fable 5.2 in the AI assistant`,zh:`AI 助手支持 Claude Fable 5.2`},body:{en:`Pick Claude Fable 5.2 in the model picker, with a 1M-token context, effort up to Max, and fast mode. If your Claude Code is older than 2.1.321, the model is shown greyed out with "Needs Claude Code 2.1.321+".`,zh:`在模型选择器中选择 Claude Fable 5.2，支持 1M token 上下文、最高 Max 的思考强度和快速模式。如果你的 Claude Code 版本低于 2.1.321，该模型会显示为灰色，并提示“Needs Claude Code 2.1.321+”。`}}],$n=[],er={version:Xn,date:Zn,highlights:Qn,fixes:$n}})))()}var nr,rr,ir,ar,or;function sr(){return(sr=e((()=>{nr=`0.16.8`,rr=`2026-11-10`,ir=[{title:{en:`Dark pages for PDFs`,zh:`PDF 深色页面`},body:{en:`Read any PDF with dark pages, from the PDF toolbar or the command palette.`,zh:`在 PDF 工具栏或命令面板中开启，即可以深色页面阅读任意 PDF。`}},{title:{en:`Two PDFs side by side`,zh:`并排阅读两个 PDF`},body:{en:`Open a PDF or a paper to the side to read it next to another, each with its own page and zoom.`,zh:`把 PDF 或论文在侧边打开，与另一个 PDF 并排阅读，各自保留页码和缩放。`}},{title:{en:`Newer Claude models in the AI assistant`,zh:`AI 助手支持更新的 Claude 模型`},body:{en:`Sonnet 5.5 and Haiku 5.5 are in the model picker, and a Claude Code that is too old for a model now says which version that model needs.`,zh:`模型选择器中新增 Sonnet 5.5 和 Haiku 5.5；如果 Claude Code 版本过低，会提示该模型需要的版本。`}}],ar=[{en:`A stray " inside a braced BibTeX field, as Zotero writes it, no longer hides every later entry or makes Add papers fail.`,zh:`BibTeX 花括号字段中多出的 "（Zotero 会这样写）不会再导致后面的条目全部消失，也不会让添加论文失败。`},{en:`In the AI assistant, the conversation scrolls with the pointer over a wide table.`,zh:`在 AI 助手中，指针停在宽表格上时也能滚动对话。`},{en:`A saved Fable choice uses Fable 5.1 when Claude Code is older than 2.1.321.`,zh:`Claude Code 版本低于 2.1.321 时，已保存的 Fable 选择会使用 Fable 5.1。`}],or={version:nr,date:rr,highlights:ir,fixes:ar}})))()}var cr,lr,ur,dr,fr;function pr(){return(pr=e((()=>{cr=`0.16.9`,lr=`2026-11-10`,ur=[{title:{en:`Know when your TeX packages are out of date`,zh:`TeX 包过期提醒`},body:{en:`Lattice tells you when your TeX packages are out of date and offers a one-click update.`,zh:`TeX 包过期时，Lattice 会提醒你，并提供一键更新。`}},{title:{en:`Newer default model in the AI assistant`,zh:`AI 助手默认使用更新的模型`},body:{en:`"sonnet" and "haiku" now mean Sonnet 5.5 and Haiku 5.5, the default model is Sonnet 5.5, and Opus 5.5 and Fable 5.2 show their real default effort.`,zh:`“sonnet” 和 “haiku” 现在指 Sonnet 5.5 和 Haiku 5.5，默认模型为 Sonnet 5.5，Opus 5.5 和 Fable 5.2 会显示真实的默认推理强度。`}}],dr=[{en:`In an Overleaf project, the PDF your build makes is no longer synced to or from Overleaf, so a collaborator's PDF can no longer replace yours when the main document sits in a subfolder (such as cvpr/main.tex). If the PDF is replaced anyway, Lattice rebuilds instead of showing someone else's PDF.`,zh:`在 Overleaf 项目中，你编译生成的 PDF 不再与 Overleaf 同步；主文档位于子文件夹（如 cvpr/main.tex）时，合作者的 PDF 不会再覆盖你的 PDF。即使 PDF 被替换，Lattice 也会重新编译，而不是显示别人的 PDF。`},{en:`Ctrl/⌘ + wheel zoom in the PDF keeps the point under the pointer instead of jumping to another page. Thanks to @Livioni.`,zh:`在 PDF 中用 Ctrl/⌘ + 滚轮缩放时，指针下的位置保持不动，不再跳到其他页。感谢 @Livioni。`},{en:`Drag-selecting text past the edge of the editor scrolls smoothly. Thanks to @wchen99998.`,zh:`拖选文本超出编辑器边缘时，滚动更加流畅。感谢 @wchen99998。`}],fr={version:cr,date:lr,highlights:ur,fixes:dr}})))()}var mr,hr,gr,_r,vr;function yr(){return(yr=e((()=>{mr=`0.7.0`,hr=`2026-10-15`,gr=[{icon:`undo`,title:{en:`Undo and redo work again`,zh:`撤销和重做恢复正常`},body:{en:`⌘Z and ⇧⌘Z reach every editor again, and Edit ▸ Undo and Redo step the focused editor's own history, including Enter, completions, brackets and paste. Both had been broken since v0.1.239.`,zh:`⌘Z 和 ⇧⌘Z 重新作用于每个编辑器，“编辑 ▸ 撤销/重做”会按当前编辑器自己的历史逐步回退，包括回车、补全、括号和粘贴。这两项自 v0.1.239 起一直失效。`}},{icon:`message`,title:{en:`Comment cards that answer in place`,zh:`就地回复的批注卡片`},body:{en:`A comment's card on the source is redrawn as the collaboration panel's thread card: Resolve is a check that confirms the result and offers Undo, and Reply is an inline field under the thread. Comments on the PDF get a hover preview and the same card on click. The note composer drops its Esc button; Esc or a press outside closes it, and a discarded note can be brought back with Undo.`,zh:`源码上的批注卡片改用协作面板的讨论卡片样式：“解决”是一个勾选，会确认结果并提供撤销；“回复”是讨论下方的内联输入框。PDF 上的批注支持悬停预览，点击后显示同样的卡片。笔记输入框去掉了 Esc 按钮，按 Esc 或点击外部即可关闭，丢弃的笔记可以用撤销找回。`}},{icon:`menu`,title:{en:`Menus close where you expect`,zh:`菜单在预期的位置关闭`},body:{en:`A press beside any menu, select or context menu only closes it instead of moving the caret, jumping the PDF or reaching an iframe, and pressing a menu's button again closes it. Menus, selects and popovers in the Agent panel and in Settings → Models / MCP / Skills now close on a press anywhere else in Lattice too.`,zh:`在任何菜单、下拉框或右键菜单旁边点击，只会关闭它，不会移动光标、跳动 PDF 或点进内嵌页面；再次点击菜单按钮也会关闭它。助手面板和“设置 → 模型 / MCP / 技能”中的菜单、下拉框和浮层，现在点击 Lattice 的其他任何地方也会关闭。`}}],_r=[{en:`Settings → Appearance gives the Color theme and Tint tiles more room, and a selected tile's ring no longer touches its name.`,zh:`“设置 → 外观”为颜色主题和色调卡片留出了更多空间，选中卡片的外框不再碰到名称。`},{en:`Tab close buttons are a 22 × 22 square inset from the tab's edges on every tab strip.`,zh:`所有标签栏上的标签关闭按钮都是 22 × 22 的方块，并与标签边缘保持间距。`}],vr={version:mr,date:hr,highlights:gr,fixes:_r}})))()}var br,xr,Sr,Cr,wr;function Tr(){return(Tr=e((()=>{br=`0.8.0`,xr=`2026-10-16`,Sr=[{icon:`feather`,title:{en:`A much smaller app`,zh:`安装包小了一半`},body:{en:`Lattice drops from about 656 MB to about 310 MB installed. The slide runtime ships only what the Open Slide dev server loads, the Synara runtime no longer bundles Pi and OpenCode (they install on demand the first time you pick them), and one shared pruner now trims both runtimes while a size gate keeps the installed app from growing back.`,zh:`安装后的 Lattice 从约 656 MB 降到约 310 MB。幻灯片运行时只带 Open Slide 开发服务器会加载的内容，Synara 运行时不再内置 Pi 和 OpenCode（第一次选用时才按需安装），同一个裁剪工具同时精简两个运行时，体积门槛防止安装包再变大。`}},{icon:`bot`,title:{en:`Synara 1.0.5 in the Agent panel`,zh:`助手面板升级到 Synara 1.0.5`}},{icon:`plug`,title:{en:`An /mcp view for the agent's MCP servers`,zh:`查看助手 MCP 服务器的 /mcp`},body:{en:`A bare /mcp lists the servers with their status, and lets you sign in, sign out, reconnect, and turn each one on or off.`,zh:`单独输入 /mcp 会列出各个服务器及其状态，可以登录、退出、重连，或逐个开启和关闭。`}},{icon:`sparkles`,title:{en:`Agent HTML visuals`,zh:`助手生成的 HTML 图示`},body:{en:`HTML the agent produces renders as a visual in the Agent panel, in a sandbox.`,zh:`助手写出的 HTML 会在助手面板里以图示呈现，运行在沙箱中。`}},{icon:`gauge`,title:{en:`Usage quota is back`,zh:`用量额度重新显示`},body:{en:`The Agent panel's usage chip shows again when you sign in to Claude through a wrapped login.`,zh:`通过封装登录使用 Claude 时，助手面板的用量标签重新出现。`}},{icon:`git`,title:{en:`Git panel empty states`,zh:`Git 面板的空状态`},body:{en:`A folder without Git shows Initialize Git instead of an error, and Pull requests explains what it needs.`,zh:`没有 Git 的文件夹会显示“初始化 Git”，而不是报错；拉取请求也会说明它需要什么。`}},{icon:`shapes`,title:{en:`Continuous corners`,zh:`连续曲率圆角`},body:{en:`Panels, dialogs, menus, cards and controls use squircle corners wherever the engine draws them.`,zh:`面板、对话框、菜单、卡片和控件在渲染引擎支持的地方都使用超椭圆圆角。`}}],Cr=[{en:`A file can be reopened from the tree after its last tab closed.`,zh:`关闭最后一个标签页后，可以从文件树重新打开该文件。`},{en:`The .bib reference list draws its first rows again when you scroll back to the top, instead of leaving a blank gap.`,zh:`滚回顶部时，.bib 参考文献列表会重新绘制前几行，不再留下一段空白。`}],wr={version:br,date:xr,highlights:Sr,fixes:Cr}})))()}var Er,Dr,Or,kr,Ar;function jr(){return(jr=e((()=>{Er=`0.9.0`,Dr=`2026-10-17`,Or=[{icon:`message`,title:{en:`Review the paper as a reviewer would`,zh:`像审稿人一样审阅全文`},body:{en:`A Review panel reads every file the root document reaches and writes a dated report: a verdict, strengths, and findings, each anchored to its passage and one click from an annotation.`,zh:`审阅面板会读完根文档引用到的每个文件，写出一份带日期的报告：结论、优点和问题，每条都定位到原文段落，一键即可添加为批注。`}},{icon:`message`,title:{en:`Answer reviewer comments`,zh:`逐条回复审稿意见`},body:{en:`Paste the venue's reviews into the Responses panel: each comment gets a fixed number (R1.1, R2.3), an owner, a reply and links to the passages that changed, and the response letter exports as Markdown or LaTeX.`,zh:`把会议或期刊的审稿意见粘贴到审稿回复面板：每条意见都有固定编号（R1.1、R2.3）、负责人、回复，以及指向修改段落的链接，回复信可以导出为 Markdown 或 LaTeX。`}},{icon:`feather`,title:{en:`Export a review PDF`,zh:`导出评阅 PDF`},body:{en:`Pick the annotations to share and export the PDF with them as standard PDF comments any reader shows.`,zh:`挑选要分享的批注，导出时以标准 PDF 注释写入，任何阅读器都能显示。`}},{icon:`menu`,title:{en:`Submission requirements and materials`,zh:`投稿要求与材料`},body:{en:`The Submission checklist keeps your own items under the automatic checks, each linked to a project file and flagged again when that file changes, with the deadline in AoE above it.`,zh:`投稿检查在自动检查下方保存你自己的条目，每条可关联一个项目文件，文件变化后会重新标记；上方显示 AoE 时区的截止时间。`}},{icon:`sparkles`,title:{en:`Export for arXiv`,zh:`导出 arXiv 提交包`},body:{en:`The source pack is built from what the last build read and checked first: every figure included, the .bbl shipped, the pack building alone, TODO comments, and arXiv's 50 MB limit.`,zh:`提交包按上次编译实际读取的文件生成，并先做检查：图片是否齐全、是否附带 .bbl、提交包能否单独编译、TODO 注释，以及 arXiv 的 50 MB 上限。`}},{icon:`shapes`,title:{en:`Figure inventory`,zh:`图片清单`},body:{en:`See every figure, where the paper uses it, and what a pre-submission check finds, and replace one with a preview you can undo.`,zh:`查看每张图片、它在论文中的引用位置以及投稿前检查的结果；替换图片前可以预览，替换后也能撤销。`}},{icon:`git`,title:{en:`Compare any two versions`,zh:`对比任意两个版本`},body:{en:`History compares any two versions as marked prose or a line diff, and exports a PDF with the changes marked.`,zh:`历史可以对比任意两个版本，以标注修改的正文或逐行差异显示，并导出标出修改的 PDF。`}},{icon:`sparkles`,title:{en:`Term rules`,zh:`术语规则`},body:{en:`A Terms panel keeps the names, spellings and English variant a paper settles on, and lists every place across the .tex files that writes a term another way.`,zh:`术语面板记录论文确定下来的名称、拼写和英语变体，并列出所有 .tex 文件中写法不一致的地方。`}},{icon:`bot`,title:{en:`Find support for a claim`,zh:`为论点查找支持文献`},body:{en:`Select a sentence and Lattice finds papers whose abstracts bear on it, each with the sentence that speaks to it and one click to cite.`,zh:`选中一句话，Lattice 会找出摘要与之相关的论文，每篇附上摘要中对应的那句话，一键即可引用。`}},{icon:`plug`,title:{en:`Link a reference manager's .bib`,zh:`关联文献管理器的 .bib`},body:{en:`A Zotero or Paperpile export outside the project stays linked, and its new papers and changed fields are shown for review before they land.`,zh:`项目之外的 Zotero 或 Paperpile 导出文件会保持关联，新增的论文和变化的字段会先列出供你确认，再写入项目。`}},{icon:`shapes`,title:{en:`Tables from pasted data`,zh:`用粘贴的数据生成表格`},body:{en:`Paste CSV or spreadsheet cells into Insert table, edit the grid, and reopen a generated table later to change it.`,zh:`在插入表格中粘贴 CSV 或电子表格单元格，编辑表格后插入；之后还能重新打开生成的表格进行修改。`}},{icon:`feather`,title:{en:`Local templates`,zh:`本地模板`},body:{en:`Start a new project from your own reusable templates, or from a blank one.`,zh:`新建项目时可以使用你自己的可复用模板，也可以从空白文档开始。`}},{icon:`gauge`,title:{en:`A faster app`,zh:`更快的应用`},body:{en:`The React Compiler now optimizes the main window, its editor, PDF and panels render independently of each other, and startup loads less JavaScript.`,zh:`React Compiler 现在会优化主窗口，编辑器、PDF 和各个面板彼此独立渲染，启动时加载的 JavaScript 也更少了。`}}],kr=[{en:`Overleaf shows "Synced" only once Overleaf has acknowledged the change.`,zh:`只有在 Overleaf 确认收到修改后，才会显示“已同步”。`},{en:`Results that arrive late from one project no longer show up in the next one after a switch.`,zh:`切换项目后，上一个项目迟到的结果不会再出现在新项目中。`},{en:`Enter in Go to line no longer types a newline into the source.`,zh:`在“跳到行”中按回车不会再往源码里插入换行。`},{en:`Save a copy after a failed save, and line jumps, act on the document on screen.`,zh:`保存失败后的“保存副本”以及跳到行，都会作用于屏幕上正在显示的文档。`},{en:`The PDF can be read from the keyboard after entering a page number or using Find.`,zh:`输入页码或使用查找后，可以继续用键盘阅读 PDF。`}],Ar={version:Er,date:Dr,highlights:Or,fixes:kr}})))()}var Mr,Nr;function Pr(){return(Pr=e((()=>{o(),f(),v(),w(),A(),I(),H(),J(),ee(),oe(),fe(),ve(),we(),Ae(),Ie(),He(),Je(),et(),ot(),ft(),vt(),wt(),At(),It(),Ht(),Jt(),en(),sn(),pn(),yn(),Tn(),jn(),Ln(),Un(),Yn(),tr(),sr(),pr(),yr(),Tr(),jr(),Mr=Object.assign({"../release-notes/0.10.0.json":a,"../release-notes/0.10.1.json":d,"../release-notes/0.11.0.json":_,"../release-notes/0.11.1.json":C,"../release-notes/0.11.2.json":k,"../release-notes/0.11.3.json":F,"../release-notes/0.11.4.json":V,"../release-notes/0.11.5.json":q,"../release-notes/0.11.6.json":$,"../release-notes/0.11.7.json":ae,"../release-notes/0.11.8.json":de,"../release-notes/0.12.0.json":_e,"../release-notes/0.12.1.json":Ce,"../release-notes/0.13.0.json":ke,"../release-notes/0.14.0.json":Fe,"../release-notes/0.14.1.json":Ve,"../release-notes/0.14.2.json":qe,"../release-notes/0.14.3.json":$e,"../release-notes/0.15.0.json":at,"../release-notes/0.15.1.json":dt,"../release-notes/0.15.2.json":_t,"../release-notes/0.15.3.json":Ct,"../release-notes/0.15.4.json":kt,"../release-notes/0.15.5.json":Ft,"../release-notes/0.15.6.json":Vt,"../release-notes/0.15.7.json":qt,"../release-notes/0.15.8.json":$t,"../release-notes/0.16.1.json":on,"../release-notes/0.16.10.json":fn,"../release-notes/0.16.11.json":vn,"../release-notes/0.16.2.json":wn,"../release-notes/0.16.3.json":An,"../release-notes/0.16.4.json":In,"../release-notes/0.16.5.json":Hn,"../release-notes/0.16.6.json":Jn,"../release-notes/0.16.7.json":er,"../release-notes/0.16.8.json":or,"../release-notes/0.16.9.json":fr,"../release-notes/0.7.0.json":vr,"../release-notes/0.8.0.json":wr,"../release-notes/0.9.0.json":Ar}),Nr=Object.values(Mr)})))()}Pr();export{Nr as bundledReleaseNotes};